    code: "#include <string>\n#include <vector>\nusing namespace std;\nstring minWindowSubsequence(const string& s, const string& t) {\n    if (t.empty()) return \"\";\n    vector<int> start(t.size(), -1);\n    int bestStart = -1, bestLength = (int)s.size() + 1;\n    for (int i = 0; i < (int)s.size(); ++i) {\n        for (int j = (int)t.size() - 1; j >= 0; --j) {\n            if (s[i] != t[j]) continue;\n            if (j == 0) start[j] = i;\n            else if (start[j - 1] != -1) start[j] = start[j - 1];\n        }\n        int from = start.back();\n        if (from != -1 && i - from + 1 < bestLength) {\n            bestLength = i - from + 1;\n            bestStart = from;\n        }\n    }\n    return bestStart < 0 ? \"\" : s.substr(bestStart, bestLength);\n}",
