  "s11-design-twitter": {
    trick: "Store each user's tweets in time order. To build a feed, heap-merge the latest tweet from the user and every followee, taking only ten posts.",
    time: "O(1) average post/follow/unfollow; O(f + 10 log(f+1)) feed",
    space: "O(T + F), tweets T and follows F; O(f) feed heap",
    code: "#include <queue>\n#include <unordered_map>\n#include <unordered_set>\n#include <vector>\nusing namespace std;\nclass Twitter {\n    struct Tweet { long long time; int id; };\n    struct FeedItem {\n        long long time;\n        int user, index, id;\n        bool operator<(const FeedItem& other) const {\n            return time < other.time;\n        }\n    };\n    long long clock = 0;\n    unordered_map<int, vector<Tweet>> tweets;\n    unordered_map<int, unordered_set<int>> following;\npublic:\n    void postTweet(int userId, int tweetId) {\n        tweets[userId].push_back({++clock, tweetId});\n    }\n    void follow(int followerId, int followeeId) {\n        if (followerId != followeeId)\n            following[followerId].insert(followeeId);\n    }\n    void unfollow(int followerId, int followeeId) {\n        auto it = following.find(followerId);\n        if (it != following.end()) it->second.erase(followeeId);\n    }\n    vector<int> getNewsFeed(int userId) {\n        priority_queue<FeedItem> heap;\n        auto addLatest = [&](int user) {\n            auto it = tweets.find(user);\n            if (it == tweets.end() || it->second.empty()) return;\n            int index = (int)it->second.size() - 1;\n            const Tweet& t = it->second[index];\n            heap.push({t.time, user, index, t.id});\n        };\n        addLatest(userId);\n        auto it = following.find(userId);\n        if (it != following.end())\n            for (int user : it->second) addLatest(user);\n        vector<int> feed;\n        while (!heap.empty() && feed.size() < 10) {\n            FeedItem current = heap.top();\n            heap.pop();\n            feed.push_back(current.id);\n            if (current.index > 0) {\n                int earlier = current.index - 1;\n                const Tweet& t = tweets[current.user][earlier];\n                heap.push({t.time, current.user, earlier, t.id});\n            }\n        }\n        return feed;\n    }\n};",
  },
